/* TNM World Wrestling Report: WCW (World Championship Wrestling).
   Everything the site shows for this promotion lives in this file. */

P.wcw = {"short": "WCW", "name": "World Championship Wrestling", "home": "Atlanta, GA", "c": "var(--wcw)", "status": "Post-Flair power vacuum. Last house show before the Bash is in the books; Baltimore cage match 7/14.", "stat": ["$513,200", "gate, 7/5–7/12 (7 dates incl. the Pro taping)"], "titles": [["World Heavyweight", "VACANT", "Flair quit and took Big Gold. New belt unveiled 7/6. Luger vs. Windham, cage, 7/14 Bash."], ["United States", "Sting", "Made Arn Anderson pass out in the Scorpion (Charleston 7/12). Vs. Koloff at the Bash."], ["World Tag Team", "VACANT", "To be crowned 7/20, Johnson City."], ["Television", "To establish", "Plan: vacant, tournament in August, final at the Omni 8/25."]], "factions": [["Luger, Harley Race & Mr. Hughes", "Hughes now Luger's full-time bodyguard after leaving the Dark Circle. World Title picture vs. Windham, then Simmons."], ["The Dark Circle", "Kevin Sullivan quit after Columbus. Cactus Jack takes over across 4 weeks of WCW Pro with One Man Gang. Bruise Brothers being courted. Target: El Gigante."], ["Paul E. Dangerously's group", "\"I didn't help anybody. I made an investment.\" Rick Rude (centerpiece), Bobby Eaton (first recruit). Paul E. got involved on Larry Zbyszko's behalf in Charleston 7/12. Arn Anderson is next on the shopping list."], ["The York Foundation", "Richard Morton (turned on Gibson 7/6) and Terry Taylor."], ["Fabulous Freebirds", "Michael Hayes back from injury 7/8 with Jimmy Garvin."]], "stories": [["The Throne Sits Empty", "Luger, with Race and Hughes in his corner, meets Barry Windham in the cage for the new World Title. Windham has called Luger out on TV twice."], ["Sting's Summer", "Sting vs. Koloff at the Bash ends that program. August: the gift-box attack and a Sting vs. Abdullah run to the Omni. Rick Rude waits underneath."], ["Mr. Wonderful", "Paul Orndorff is unbeaten on the tour (Steiner, Rich, Big Josh). JYD at the Bash, then the TV Title tournament."], ["Pillman vs. Liger", "1–0 Pillman from Philly. The rematch is agreed for Baltimore."], ["Pro-only: Killer Bees vs. Murdoch & Reed", "The masked-switch feud plays out across 4 episodes of WCW Pro and blows off No DQ, no masks."]], "desk": ["Tom Zenk signed 7/11 (35 shows, B-tier money). He debuts at the Bash; Paul E. has been calling him.", "Richard Morton and Jimmy Garvin no-showed Charleston 7/12. Both are booked for the Bash.", "Charleston drew 3,200 ($38,400), the smallest house since Flair left, on the best-rated house show of the loop.", "Harley Race goes manager-only at the Bash.", "Hayes contract count unknown.", "Dustin Rhodes out until the fall (neck). On screen: blamed on Paul E., Rude and Eaton (Greenville 7/13).", "Rude and Abdullah are working AJPW. Check blackout dates before booking.", "Arn vs. Zbyszko needs a finish that lets both join Paul E. later (no contest or double count-out).", "Autumn Armageddon still has no date."], "roster": [["Abdullah The Butcher", "Also AJPW. Keep matches short and gimmicked"], ["Arn Anderson", ""], ["B. Brian Blair", "Killer Bees"], ["Barry Windham", "World Title challenger"], ["Big Josh", ""], ["Big Van Vader", ""], ["Bill Irwin", ""], ["Black Bart", ""], ["Bobby Eaton", "w/ Paul E."], ["Brian Pillman", ""], ["Butch Reed", "w/ Murdoch"], ["Cactus Jack", "New Dark Circle leader"], ["Diamond Dallas Page", ""], ["Dick Murdoch", "w/ Reed"], ["Don Harris", "Bruise Brothers"], ["Dustin Rhodes", "INJ:Neck, out until fall"], ["El Gigante", ""], ["Great Muta", ""], ["Harley Race", "Manager"], ["Jim Brunzell", "Killer Bees"], ["Jimmy Garvin", "Freebirds. No-show 7/12"], ["Junk Yard Dog", "vs. Orndorff"], ["Jushin Liger", ""], ["Larry Zbyszko", ""], ["Lex Luger", "w/ Harley Race"], ["Michael Hayes", "Freebirds"], ["Mr. Hughes", "Luger's bodyguard"], ["Nikita Koloff", ""], ["One Man Gang", "Dark Circle"], ["Ozz", ""], ["Paul E. Dangerously", "Manager"], ["Paul Orndorff", "TV Title path"], ["PN News", ""], ["Richard Morton", "York Foundation. No-show 7/12"], ["Rick Rude", "Also AJPW. w/ Paul E."], ["Rick Steiner", ""], ["Robert Gibson", ""], ["Ron Harris", "Bruise Brothers"], ["Ron Simmons", ""], ["Steve Armstrong", "Young Pistols"], ["Sting", "U.S. Champion"], ["Terry Taylor", "York Foundation"], ["Tom Zenk", "Signed 7/11/91. Debuts at the Bash"], ["Tommy Rich", ""], ["Tracy Smothers", "Young Pistols"]], "departures": [["Kevin Sullivan", "Quit 7/8 after Columbus. In talks with CMLL; nothing signed."], ["Ric Flair", "Quit. Took the Big Gold belt. Signed with USWA."]], "asOf": "1991-07-12"};

E.push(...[{"d": "1991-07-05", "p": "wcw", "city": "Philadelphia, PA", "venue": "Civic Center", "type": "Premium house show", "gate": "10,000 · $200,000", "rate": "***1/2", "big": 1, "link": "WCW_PHIL", "m": [["Arn Anderson vs. Junk Yard Dog", "Arn (DDT)", "3/4*"], ["Bruise Brothers vs. Young Pistols", "D. Harris pins Armstrong. Debut", "1/4*"], ["Brian Pillman vs. Jushin Liger", "Pillman (crucifix)", "***3/4"], ["Sullivan, Hughes & OMG vs. Killer Bees & Dustin Rhodes", "Hughes pins Brunzell", "***1/4"], ["Lex Luger vs. Nikita Koloff", "Luger (rolling reverse cradle)", "**"], ["Paul Orndorff vs. Rick Steiner", "Orndorff (piledriver). Upset", "****1/2"], ["Sting & Barry Windham vs. Big Van Vader & Great Muta", "Sting pins Vader", "****"]], "n": ["The Dark Circle is named.", "Windham wants the World Title at the Bash."]}, {"d": "1991-07-06", "p": "wcw", "city": "Atlanta, GA", "venue": "Center Stage", "type": "WCW Saturday Night (TBS)", "link": "WCW_SATU", "gate": "1,050 · $10,500", "rate": "**", "m": [["Jushin Liger vs. Terry Taylor", "Liger (moonsault)", "***1/2"], ["Bruise Brothers vs. Bill Irwin & Butch Reed", "D. Harris pins Irwin", "-3/4*"], ["Rock 'n' Roll Express vs. Bobby Eaton & DDP", "Gibson pins DDP. Morton turns on Gibson after", "**"], ["Kevin Sullivan vs. Dustin Rhodes", "Sullivan by DQ. Gigante saves", "**"], ["Barry Windham vs. Ozz", "Windham (superplex)", "**3/4"]], "n": ["Jim Herd: Flair is gone, new World Title belt unveiled.", "Bash matches set: Luger vs. Windham (cage), Pillman vs. Liger, Orndorff vs. JYD, Morton vs. Gibson, Bruise Brothers vs. News & Rich, Gigante vs. OMG, Arn vs. Zbyszko, Simmons vs. Ozz."]}, {"d": "1991-07-07", "p": "wcw", "city": "Richmond, VA", "venue": "Coliseum", "type": "House show", "gate": "6,000 · $72,000", "link": "WCW_RICH", "rate": "**1/2", "m": [["Young Pistols vs. York Foundation", "Smothers pins Taylor", "**"], ["El Gigante vs. Butch Reed", "Gigante (chokeslam)", "1/2*"], ["Brian Pillman vs. Bobby Eaton", "Pillman. Paul E. interferes", "***1/4"], ["Arn Anderson vs. Big Josh", "Arn (DDT)", "*1/4"], ["Bruise Brothers vs. Killer Bees", "D. Harris pins Brunzell", "*3/4"], ["Paul Orndorff vs. Tommy Rich", "Orndorff (piledriver). Steiner interferes", "****1/4"], ["Rick Rude vs. Dustin Rhodes", "Rude by count-out. Paul E. interferes", "**1/4"], ["Sting & Windham vs. Luger & Mr. Hughes", "Sting submits Hughes (Scorpion)", "**3/4"]]}, {"d": "1991-07-08", "p": "wcw", "city": "Columbus, GA", "venue": "Civic Center", "type": "House show", "gate": "4,500 · $67,500", "link": "WCW_COLU", "rate": "**1/2", "m": [["Bobby Eaton vs. Tracy Smothers", "Eaton (Alabama Jam). Paul E. interferes", "***"], ["Larry Zbyszko vs. Butch Reed", "Zbyszko (brainbuster)", "**3/4"], ["Abdullah the Butcher vs. Bill Irwin", "Abdullah (elbow drop)", "-**1/4"], ["Arn Anderson vs. Steve Armstrong", "Arn (DDT)", "**"], ["Jushin Liger vs. Dustin Rhodes", "20:00 draw. Dustin hurts his neck", "****"], ["Dark Circle vs. Gibson, News & Rich", "Hughes pins Rich. Sullivan's last match", "*1/4"], ["Freebirds vs. Killer Bees", "Hayes pins Blair. Freebirds return", "***3/4"], ["Sting vs. Ozz (U.S. Title)", "Sting retains (Scorpion)", "**3/4"], ["Steiner & Koloff vs. Vader & Muta", "Steiner pins Muta", "***"]], "n": ["Kevin Sullivan quits WCW, effective immediately.", "Dustin Rhodes out until the fall."]}, {"d": "1991-07-09", "p": "wcw", "city": "Tallahassee, FL", "venue": "Leon County Civic Center", "type": "WCW Pro taping (Episodes 1–4)", "link": "WCW_PRO_", "m": [["Ep 1 (7/13): TV Title QF, Rick Steiner vs. Arn Anderson", "Steiner (Steiner Bulldog)", ""], ["Ep 2 (7/20): TV Title QF, Tommy Rich vs. Bobby Eaton (w/ Paul E.)", "Rich (upset)", ""], ["Ep 3 (7/27): TV Title SF, Rick Steiner vs. Tommy Rich", "Steiner. Orndorff piledrives Rich on the floor", ""], ["Ep 4 (8/3): TV Title Final, Paul Orndorff vs. Rick Steiner", "Orndorff (feet on the ropes). New TV Champion", ""]], "n": ["One crowd for all four episodes: 5,200 at $12, plus $7,800 in merchandise ($1.50 a head). Counted once, here.", "Each episode airs and counts as a card on its air date (7/13, 7/20, 7/27, 8/3).", "Pro-only feud: Killer Bees vs. Murdoch & Reed. Dark Circle arc: Cactus Jack takes over."], "gate": "5,200 · $62,400"}, {"d": "1991-07-11", "p": "wcw", "city": "Columbia, SC", "venue": "Carolina Coliseum", "type": "House show", "gate": "5,200 · $62,400", "rate": "**3/4", "m": [["York Foundation vs. Young Pistols", "Morton pins Smothers (roll-up)", "**1/2"], ["El Gigante vs. Bill Irwin", "Gigante (chokeslam)", "-*3/4"], ["Ron Simmons vs. Butch Reed", "Simmons (spinebuster)", "***"], ["Jushin Liger vs. Diamond Dallas Page", "Liger (Liger Bomb)", "**3/4"], ["Bobby Eaton vs. Brian Pillman", "Eaton (Alabama Jam). Paul E. at ringside", "***1/4"], ["Arn Anderson vs. Robert Gibson", "Arn (DDT)", "*1/2"], ["Freebirds vs. PN News & Tommy Rich", "Hayes pins Rich (DDT)", "**1/2"], ["Vader & Muta vs. Steiner & Koloff", "Vader pins Koloff. Race interferes", "***1/4"], ["Luger & Mr. Hughes vs. Sting & Windham", "Luger & Hughes by DQ (Windham uses the chair)", "***1/2"]], "n": ["Merchandise: $52,000, about $10 a head.", "Vader & Muta finally win one."]}, {"d": "1991-07-12", "p": "wcw", "city": "Charleston, SC", "venue": "McAllister Fieldhouse", "type": "House show", "gate": "3,200 · $38,400", "rate": "***", "m": [["Young Pistols vs. Bill Irwin & Butch Reed", "Smothers pins Irwin (dropkick)", "1/2*"], ["Cactus Jack vs. Black Bart", "Cactus (double-arm DDT)", "*1/4"], ["Paul Orndorff vs. Big Josh", "Orndorff (piledriver)", "**"], ["Jushin Liger vs. Terry Taylor", "Liger (moonsault). Morton no-showed", "**1/2"], ["Bobby Eaton vs. Robert Gibson", "Eaton (Alabama Jam). Paul E. interferes", "*1/4"], ["Rick Steiner vs. Great Muta", "Steiner", "***3/4"], ["Pillman & Rich vs. Hayes & DDP", "Pillman pins DDP (cross body). Garvin no-showed", "***1/2"], ["Ron Simmons vs. Larry Zbyszko", "Simmons (powerslam). Paul E. interferes for Zbyszko", "***"], ["Barry Windham vs. Mr. Hughes", "Windham, clean (superplex). Luger ringside", "**1/2"], ["Sting vs. Arn Anderson (U.S. Title)", "Sting retains. Arn passes out in the Scorpion", "***3/4"]], "n": ["Best house show rating since Philly.", "Richard Morton and Jimmy Garvin no-showed.", "Merchandise: $9,600, about $3 a head."]}, {"d": "1991-07-13", "p": "wcw", "city": "Greenville, SC", "venue": "Memorial Auditorium", "type": "WCW Saturday Night (go-home)", "m": [["Angle: Paul E., Rude & Eaton ambush Dustin Rhodes", "Rude Awakening on the injured neck. Steiner too late. Stretcher", ""]], "plan": 1}, {"d": "1991-07-13", "p": "wcw", "city": "Tallahassee, FL", "venue": "Leon County Civic Center (taped 7/9)", "type": "WCW Pro, Episode 1", "ran": 1, "rate": "**1/4", "m": [["Barry Windham vs. Dana McKinney", "Windham (superplex)", ""], ["Fabulous Freebirds vs. Twilight Zone #1 & #2", "Hayes pins Twilight Zone #2", ""], ["Killer Bees vs. Dick Murdoch & Butch Reed", "Blair cradles Murdoch. Murdoch cries foul", "**1/2"], ["TV Title QF: Paul Orndorff vs. Terry Taylor", "Orndorff (piledriver)", "*3/4"], ["TV Title QF: Rick Steiner vs. Arn Anderson", "Steiner (Steiner Bulldog)", "**1/2"]], "n": ["Segments: tournament bracket revealed; Saturday Night recap; Paul E.: \"I make investments\"; the Dark Circle without Sullivan (Hughes walks out); Dustin Rhodes' taped promo.", "Taping crowd and gate are counted on 7/9."]}, {"d": "1991-07-14", "p": "wcw", "city": "Baltimore, MD", "venue": "Baltimore Arena", "type": "The Great American Bash '91", "big": 1, "m": [["Steel cage, vacant World Title: Lex Luger vs. Barry Windham", "Luger. Hughes slips in a chair; piledriver", ""], ["U.S. Title: Sting vs. Nikita Koloff", "Sting retains", ""], ["Rick Rude vs. Rick Steiner", "Rude (phone shot). \"You're next,\" to Sting", ""], ["Paul Orndorff vs. Junk Yard Dog", "Orndorff, clean (piledriver)", ""], ["Brian Pillman vs. Jushin Liger", "", ""], ["Arn Anderson vs. Larry Zbyszko", "No contest or double count-out (plan)", ""], ["El Gigante vs. One Man Gang", "Cactus at ringside costs Gigante (plan)", ""], ["Ron Simmons vs. Ozz", "", ""], ["Richard Morton vs. Robert Gibson", "", ""], ["Segment: Tom Zenk's WCW debut (w/ Paul E. Dangerously & Bobby Eaton)", "Paul E. unveils his \"investment\"", ""], ["Bruise Brothers vs. PN News & Tommy Rich", "", ""], ["Cactus Jack vs. Big Van Vader", "", ""], ["Six-man: Freebirds & Diamond Dallas Page vs. Young Pistols & Big Josh", "Big Josh replaces the injured Dustin Rhodes", ""]], "n": ["Head to head with WWF WrestleFest '91 the same night.", "Abdullah pulled (AJPW). Cactus vs. Vader confirmed in his place."]}, {"d": "1991-07-20", "p": "wcw", "city": "Johnson City, TN", "venue": "", "type": "Saturday Night: tag titles crowned"}, {"d": "1991-07-26", "p": "wcw", "city": "Oakland, CA", "venue": "Coliseum", "type": "House show"}, {"d": "1991-07-27", "p": "wcw", "city": "Phoenix, AZ", "venue": "", "type": "Saturday Night"}, {"d": "1991-08-25", "p": "wcw", "city": "Atlanta, GA", "venue": "The Omni", "type": "GAB tour finale", "big": 1, "m": [["U.S. Title: Sting vs. Abdullah (Texas Death or cage)", "Sting, clean. Rude attacks after", ""], ["TV Title final: Paul Orndorff vs. Rick Steiner", "Orndorff (ropes for leverage)", ""]], "plan": 1}]);

Object.assign(ARTICLES, {"wcw-abdullah-skips-bash": {"p": "wcw", "news": 1, "by": "Newsletter staff", "date": "1991-07-13", "region": "Atlanta Report", "kicker": "WCW · Backstage", "title": "Abdullah Skips the Bash", "dek": "WCW pulled Abdullah the Butcher off the Great American Bash rather than fly him in from Hiroshima the night before. Cactus Jack gets Big Van Vader instead.", "body": [["p", "Abdullah the Butcher won't be in Baltimore on Sunday. He was originally advertised against Cactus Jack on the Bash, but he's booked with All Japan in Hiroshima on Saturday the 13th, and WCW decided it wasn't worth gambling a pay-per-view spot on a Pacific crossing that would put him in the building with a few hours to spare."], ["p", "It's the second time this month the Japan schedule has caught up with him. Abdullah was advertised as \"also appearing\" in Columbus, Georgia on July 8 and then wrestled in Kanazawa the next night. Nobody in either office is going to say that was a problem, but it got noticed, and the Bash decision looks like WCW not wanting to find out what happens on a show that matters."], ["h", "What it means"], ["p", "Cactus Jack moves to Big Van Vader, which is a better match anyway. Abdullah's real WCW program is supposed to be against Sting in August, with the blow-off at the Omni. All Japan has him in a Texas Death Match with Misawa at Budokan on 7/27 to avenge what he did to Giant Baba, so he won't be back stateside until the end of the month at the earliest."]], "facts": [["Pulled from", "Great American Bash, 7/14"], ["Instead", "AJPW Hiroshima, 7/13"], ["Replacement", "Cactus Jack vs. Big Van Vader"], ["Earlier overlap", "WCW Columbus 7/8, AJPW Kanazawa 7/9"], ["August", "Sting program"], ["Budokan", "Texas Death vs. Misawa, 7/27"]], "factTitle": "The Schedule"}, "wcw-sullivan-quits": {"p": "wcw", "news": 1, "by": "Newsletter staff", "date": "1991-07-09", "region": "Atlanta Report", "kicker": "WCW · Backstage", "title": "Sullivan Walks", "dek": "Kevin Sullivan quit WCW after Columbus, reportedly over candles. Cactus Jack is the name being mentioned to take over the Dark Circle.", "body": [["p", "Kevin Sullivan is gone from WCW, effective immediately, after the July 8 show in Columbus, Georgia. His last match was the Dark Circle six-man that night, when Mr. Hughes pinned Tommy Rich with a sidewalk slam (*1/4). He didn't do the job on the way out. He just left."], ["p", "The story going around is almost too good. Jim Herd fined Sullivan after one of the Dark Circle candles singed the backdrop at Center Stage in Atlanta, then banned the candles altogether. The quote making the rounds is that Herd told him to \"use a flashlight.\" Sullivan didn't take it well. Whether that's the whole story or just the last straw is anyone's guess, but it's hard to run a cult leader gimmick when the boss won't let you light anything."], ["h", "Where he goes"], ["p", "The two names mentioned are the USWA, where he has history and could slot in with Terry Funk's Texas Bunch, and CMLL, where Satánico is building a rudo faction that could use someone like him. Either would make sense. Neither is confirmed."], ["h", "The Dark Circle without its leader"], ["p", "The Dark Circle was named just a week ago in Philadelphia, with Sullivan, Hughes and One Man Gang. Losing the leader that fast would usually kill a group. The word is it won't. Cactus Jack is the name being mentioned to take it over, with the transition expected to play out on WCW Pro over the next month, and Hughes moving over to work as Lex Luger's full-time bodyguard."], ["p", "If that's the plan, it's a good one. Cactus is wilder than Sullivan ever was, he has nothing to do right now, and the Bruise Brothers were already being lined up to join. Sullivan's last promo in Atlanta was about how \"the circle will grow.\" It may grow faster without him."]], "facts": [["Left", "WCW, after Columbus 7/8"], ["Last match", "Dark Circle six-man win"], ["Reason (reported)", "Fined, candles banned"], ["Rumored", "USWA or CMLL"], ["Dark Circle", "Hughes, One Man Gang"]], "factTitle": "The Departure"}, "wcw-dustin-injured": {"p": "wcw", "news": 1, "by": "Newsletter staff", "date": "1991-07-09", "region": "Atlanta Report", "kicker": "WCW · Injury Report", "title": "Dustin Down", "dek": "Dustin Rhodes had the match of his life with Jushin Liger in Columbus and hurt his neck doing it. He won't be back until the fall, and the Bash card has a hole in it.", "body": [["p", "Dustin Rhodes suffered a neck injury in his 20:00 draw with Jushin Liger in Columbus on July 8. The match was excellent, ****, the best on the card, and it went five minutes longer than it was supposed to. The original estimate had him missing a couple of weeks. He's now expected to be out until the fall."], ["p", "It's a real blow. Dustin has been one of the busiest babyfaces in the company since Flair left. He lost a Rick Rude count-out in Richmond with Paul E. Dangerously getting involved, and he was booked in the Freebirds six-man at the Bash with the Young Pistols. That match now needs a new partner."], ["h", "The match"], ["p", "Liger vs. Dustin was the match that told you Dustin is going to be a star. Liger has been having great matches with everybody (Pillman in Philly at ***3/4, Terry Taylor on TV at ***1/2), and Dustin hung with him for twenty minutes. That's the frustrating part. He was just hitting his stride."], ["h", "How they handle it"], ["p", "The word is the injury will be worked into a storyline rather than just explained away, and there are obvious candidates to blame. Rude and Paul E. have already gone after him once. Bobby Eaton is Paul E.'s first recruit. If they're smart, Dustin comes back in the fall as a babyface with a reason to want revenge on somebody, and the time off makes him a bigger deal than he was when he left."], ["p", "In the meantime, the company is down another top-half babyface in a month when it already lost Flair, and that matters."]], "facts": [["Injury", "Neck"], ["When", "Liger vs. Dustin, Columbus 7/8"], ["Match", "20:00 draw, ****"], ["Expected back", "The fall"], ["Bash spot", "Freebirds six-man, partner needed"]], "factTitle": "Injury Report"}, "wcw-observer-notes-0708": {"p": "wcw", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-09", "region": "Atlanta Report", "kicker": "WCW · Backstage Notes", "title": "Backstage Notes: Columbus", "dek": "Kevin Sullivan walks out over the candles, and Rick Rude keeps flying back and forth to Japan.", "factTitle": "Filed from", "facts": [["Show", "Columbus, GA, 7/8"], ["Gate", "4,500 · $67,500"], ["Card", "**1/2"]], "body": [["h", "Columbus, GA"], ["p", "Kevin Sullivan quit WCW after Columbus. Backstage story: Jim Herd fined him after a Dark Circle candle singed the Center Stage backdrop and banned the candles (\"use a flashlight\"), so Sullivan walked out. Rumored destinations are the USWA (Memphis ties, Terry Funk's group) or CMLL (Satánico's rudo faction)."], ["h", "Columbus, GA"], ["p", "Rick Rude wasn't on the card. He was traveling back to Japan for All Japan's Nagoya show on 7/11, the latest leg of a summer spent flying across the Pacific to keep both promotions' dates."]]}, "wcw-orndorff-rich": {"p": "wcw", "news": 1, "by": "Newsletter staff", "date": "1991-07-09", "region": "Atlanta Report", "kicker": "WCW · Richmond Coliseum, July 7", "title": "Orndorff–Rich: ****1/4", "dek": "Paul Orndorff has wrestled two matches since coming back to WCW. One went ****1/2. The other went ****1/4. Nobody saw this coming.", "body": [["p", "The best match on the Richmond house show on July 7 was Paul Orndorff vs. Tommy Rich, and it wasn't close. Orndorff won with the piledriver at 12:25 in a match that got ****1/4. On a card rated **1/2, in front of 6,000 who paid $72,000, it was the match people were talking about on the way out."], ["p", "Two nights earlier in Philadelphia, Orndorff upset Rick Steiner in ****1/2, the best match of that show and the best match WCW has had all month. That's two of the best matches in the company in his first two nights, and the man is 41 years old."], ["h", "Tommy Rich"], ["p", "Credit to Rich, too. He's mostly been a body in tag matches lately, and he made this a real fight. He's the kind of veteran who can have a great match with the right opponent and a forgettable one with the wrong one, and Orndorff was the right one."], ["h", "The Steiner factor"], ["p", "The finish included Rick Steiner interfering against Orndorff. That's a sign WCW knows what it has. Steiner wants Orndorff back after Philadelphia, and he's willing to cost him a match to get it. There's a three-way story here between Orndorff, Steiner and anyone else who wants to prove they're the best wrestler in the company."], ["p", "Orndorff gets the Junk Yard Dog at the Bash, which is a step down in opponent, and there has been talk of building toward the vacant Television Title. If WCW is smart, it gives the TV belt to the guy who keeps having the best match on the card. Orndorff isn't signed long term, which is the one thing to keep an eye on."]], "facts": [["Match", "Orndorff d. Tommy Rich"], ["Finish", "Piledriver, 12:25"], ["Rating", "****1/4"], ["Crowd", "6,000 · $72,000"], ["Previous", "d. Rick Steiner, ****1/2 (7/5)"], ["Bash", "vs. Junk Yard Dog"]], "factTitle": "The Match"}, "wcw-freebirds-return": {"p": "wcw", "news": 1, "by": "Newsletter staff", "date": "1991-07-09", "region": "Atlanta Report", "kicker": "WCW · Columbus Civic Center, July 8", "title": "The Freebirds Fly Again", "dek": "Michael Hayes came back from injury, the Freebirds beat the Killer Bees in the second-best match on the show, and the building was more than half empty.", "body": [["p", "The Fabulous Freebirds are back together. Michael Hayes returned from his injury in Columbus, Georgia on July 8, and he and Jimmy Garvin beat the Killer Bees when Hayes pinned B. Brian Blair with the DDT at 12:36. It got ***3/4, second only to Liger vs. Dustin on the card."], ["p", "The match was good. The Bees are a reliable team, Hayes looked fine for a guy coming off injury, and Garvin did a lot of the work. The reunion had been advertised on TV in Atlanta, which is what makes the next part a problem."], ["h", "The house"], ["p", "Columbus drew 4,500 in a 10,000-seat building, 45% full, for $67,500. Richmond the night before drew 6,000 for $72,000 at a lower average ticket. This was supposed to be the night the Freebirds reunion sold tickets, and it didn't. It's the first soft house of the tour since Flair left, and the warning sign is that the company advertised its reunion angle and it didn't move the needle."], ["p", "To be fair, it was a Monday night. And the rest of the card had real problems, including Abdullah vs. Bill Irwin at minus **1/4. But the Freebirds were supposed to be a draw in the South, and that wasn't a drawing house."], ["h", "The Bash"], ["p", "The Freebirds are booked at the Bash in a six-man against the Young Pistols and Dustin Rhodes. Dustin hurt his neck the same night, so that match needs a new partner. If they want the reunion to mean something, Baltimore is where it needs to happen."]], "facts": [["Match", "Freebirds d. Killer Bees"], ["Finish", "Hayes DDT on Blair, 12:36"], ["Rating", "***3/4"], ["Crowd", "4,500 (45% of 10,000)"], ["Gate", "$67,500"], ["Bash", "vs. Young Pistols & TBA"]], "factTitle": "The Return"}, "world-super-sunday": {"p": "wcw", "news": 1, "by": "Newsletter staff", "date": "1991-07-09", "region": "World Report", "kicker": "World · Sunday, July 14", "title": "Super Sunday", "dek": "WCW's Great American Bash and the WWF's WrestleFest '91 go head to head on the same night. One is in an arena in Baltimore. The other is in a baseball stadium.", "body": [["p", "For the first time in a while, WCW and the WWF are running their big summer shows on the same night. On Sunday, July 14, WCW has The Great American Bash at the Baltimore Arena. The same night, the WWF has WrestleFest '91 at Busch Stadium in St. Louis."], ["h", "The cards"], ["p", "The WWF is selling Hulk Hogan vs. Sgt. Slaughter for the WWF Title, with Hacksaw Jim Duggan as Hogan's hand-picked enforcer. In a stadium with 57,676 seats, the WWF is betting Hogan can still fill a ballpark. Underneath: the Rockers get the Nasty Boys for the tag titles, Warrior and the Undertaker go one more time, Mr. Perfect defends the Intercontinental Title against Greg Valentine, Tenryu and Kitao face Demolition, and Big Boss Man is at ringside for Tito Santana vs. the Mountie."], ["p", "WCW is selling a card. Lex Luger vs. Barry Windham in a cage for the vacant World Title. Sting vs. Nikita Koloff for the U.S. Title. Rick Rude vs. Rick Steiner. Paul Orndorff vs. the Junk Yard Dog. Brian Pillman vs. Jushin Liger, which might be the best match of the night on either show. It's a deeper card. It also doesn't have Ric Flair, which is the problem WCW has been trying to solve for a week."], ["h", "Who wins"], ["p", "The WWF will win the night in attendance and money, and it isn't going to be close. Busch Stadium against the Baltimore Arena isn't a fair fight. The better question is which show people are talking about Monday morning. A new world champion crowned in a cage is a story. Hogan beating Slaughter, again, is a result everyone already expects."], ["h", "The rest of the world"], ["p", "It's a big weekend everywhere. All Japan runs its six-man special in Hiroshima the night before. New Japan is in Hiroshima the same night. CMLL has its rudos vs. técnicos showcase in Guadalajara. And the USWA runs Louisville on Saturday with Bret and Kerry teaming against Andre. If you want to watch wrestling this weekend, you won't run out."]], "facts": [["WCW", "Great American Bash, Baltimore Arena"], ["WCW main", "Luger vs. Windham, cage, vacant title"], ["WWF", "WrestleFest '91, Busch Stadium"], ["WWF main", "Hogan vs. Slaughter, Duggan as enforcer"], ["Stadium capacity", "57,676"], ["Also 7/14", "NJPW Hiroshima, CMLL Guadalajara"]], "factTitle": "The Night"}, "wcw-stings-summer": {"p": "wcw", "kicker": "Cover Story · United States Championship", "title": "Sting's Summer", "dek": "Three nights, three wins and one very long list of men who want the United States Championship. The Stinger is the hottest champion in WCW. That makes him the biggest target.", "by": "By the WCW Magazine staff", "date": "1991-07-09", "body": [["p", "If you want to know who has carried World Championship Wrestling through the first week without Ric Flair, look for the face paint. While the main-event picture tore itself apart over an empty throne, Sting went out every night and won. He has worked three main events in four days on the Great American Bash tour, and he has not lost one of them."], ["p", "It started in Philadelphia on July 5, in what may be the match of the summer. Sting and Barry Windham went 26 minutes with Big Van Vader and the Great Muta, two of the most dangerous men in the sport, and the Civic Center crowd of 10,000 never sat down. The finish belonged to Sting: a flying cross body off the top, right onto Vader, for the one, two, three. Pinning Vader clean is something very few men alive can say they have done."], ["h", "The Scorpion Stings"], ["p", "Two nights later in Richmond, Sting and Windham met Lex Luger and Mr. Hughes in the main event. Harley Race got involved against Windham, and for a moment it looked like the champion's crew would steal another one. Then Sting locked Hughes in the Scorpion Deathlock, and the big man had nowhere to go. Hughes submitted in the middle of the ring."], ["p", "In Columbus on July 8, the United States Championship was on the line against Ozz. Ozz never tapped, and he never got out, either. He passed out in the Scorpion Deathlock, and the referee called it. Sting is still your champion."], ["p", "That's three main events, three wins, and two of them by the same hold. Word around the locker room is that nobody wants to be the next man caught in it."], ["h", "Baltimore: Nikita"], ["p", "Next up is the biggest one yet. On Sunday at The Great American Bash, Sting defends the U.S. Title against Nikita Koloff."], ["p", "Koloff comes to Baltimore with something to prove. He lost to Lex Luger in Philadelphia and wants that match back, but first he wants gold. He bounced back in Columbus, teaming with Rick Steiner to beat Vader and Muta, and he went face to face with Sting on Saturday Night in Atlanta. Neither man backed down an inch."], ["p", "Koloff is as strong as anyone Sting has faced, and he has the Russian Sickle to end it with one swing. Sting has the Scorpion and a crowd that will be on its feet from the first bell. Something has to give."], ["h", "Ravishing Intentions"], ["p", "And whatever happens Sunday, Sting will not have long to celebrate."], ["p", "On Saturday Night, viewers saw a taped message from Rick Rude, filmed in Sendai, Japan, where he is in the middle of an All Japan tour. Rude made it clear he plans to deal with Rick Steiner at the Bash first. After that, he said, he is coming for Sting's United States Championship."], ["p", "Rude has been backing it up. In Richmond he beat Dustin Rhodes by count-out, and Paul E. Dangerously was at ringside, putting his nose and his oversized phone right where they didn't belong. Rude has flown back and forth across the Pacific to keep his WCW dates. That kind of commitment usually means a man wants something very badly."], ["p", "Then there's Paul E. In three shows he has interfered three times, for Bobby Eaton twice and for Rude once. He keeps insisting he hasn't helped anybody. He calls it an investment. Investors expect a return, and the most valuable piece of property in WCW right now might be the belt around Sting's waist."], ["h", "The Bottom Line"], ["p", "Sting is hot, the U.S. Title has never looked better, and the line of challengers gets longer every week. Koloff on Sunday. Rude waiting in the wings. And Paul E., phone in hand, watching everything."], ["p", "It's going to be a long, hot summer for the Stinger. He wouldn't have it any other way."]], "facts": [["Champion", "Sting, United States Heavyweight Champion"], ["7/5 Philadelphia", "W: w/ Windham d. Vader & Muta. Pinned Vader (****)"], ["7/7 Richmond", "W: w/ Windham d. Luger & Hughes. Hughes submits (**3/4)"], ["7/8 Columbus", "W: d. Ozz, title retained. Scorpion (**3/4)"], ["Next defense", "Nikita Koloff, The Great American Bash, 7/14"], ["Waiting", "Ravishing Rick Rude (w/ Paul E. Dangerously)"]], "factTitle": "The Stinger's Scorecard"}, "wcw-throne-sits-empty": {"p": "wcw", "kicker": "WCW · The Great American Bash · Baltimore, July 14", "title": "The Throne Sits Empty", "dek": "Ric Flair walked out and took Big Gold with him. On Sunday, Lex Luger and Barry Windham walk into a steel cage to decide who sits in the chair he left behind.", "by": "By the WCW Magazine staff", "date": "1991-07-09", "body": [["p", "For the first time in years, nobody in World Championship Wrestling can call himself the champion of the world. Ric Flair is gone. So is the belt. The Big Gold title he carried out the door has turned up in Memphis, where Flair has signed with the USWA, and WCW has been left with an empty throne and a power vacuum the size of the Omni."], ["p", "Jim Herd addressed it at the top of Saturday Night from Center Stage in Atlanta on July 6. Flair, he said, was no longer with the company, and the title he took with him no longer represents WCW. Then he unveiled a brand-new World Heavyweight Championship and announced how it would be filled: Lex Luger against Barry Windham, inside a steel cage, at The Great American Bash in Baltimore."], ["h", "The Total Package"], ["p", "Luger arrives at the Bash looking more like a champion every night, and acting less like the man fans cheered for. In the Philadelphia Civic Center on July 5 he beat Nikita Koloff with a rolling reverse cradle, a win that said as much about opportunism as power. The arrogance has grown by the day, and so has the company he keeps."], ["p", "Harley Race is in his corner now, and Race has been there before: seven times a world champion, and nobody in the building knows better what it takes to win one. Mr. Hughes has been at Luger's side more and more, too. In Richmond on July 7, when Luger and Hughes tagged against Sting and Windham, Race got involved against Windham. It didn't save the night, and Sting made Hughes tap to the Scorpion Deathlock, but Luger walked out without taking the fall. That is the pattern: Luger rarely pays the price himself."], ["p", "When Windham called him out on Saturday Night, Luger didn't come to the ring. He answered from the stage, with Race and Hughes beside him. Read into that what you will."], ["h", "The Lariat"], ["p", "Windham has been building to this since Philadelphia. He and Sting beat Big Van Vader and the Great Muta in a 26-minute main event that some in attendance called the best match of the summer, and when it was over, Windham made sure the cameras saw him gesture toward the title picture. He wanted Baltimore, and he got it."], ["p", "In Atlanta he took apart Ozz with a superplex, then grabbed the microphone and called Luger by name. Ron Simmons came out to back him up against Ozz, which tells you where the locker room stands. Windham doesn't have a manager, a bodyguard or a plan B. He has a lariat, a cage door that locks from the outside, and a chance to prove that the best pure wrestler left in WCW is also its rightful champion."], ["h", "Why the Cage"], ["p", "The steel is there for one reason: to keep everyone else out. A cage takes Harley Race off the apron and Mr. Hughes off the floor, or at least it is supposed to. Luger has built his recent run on the help around him. Windham has built his on doing it alone. Inside the cage, in theory, neither man can lean on anything but himself."], ["p", "In theory. Cage doors open. Referees get distracted. And nobody in Baltimore will be watching the door more closely than Barry Windham."], ["h", "What Else Is Riding on Baltimore"], ["p", "The World Title is the headline, but it won't be the only thing decided. Sting defends the United States Championship against Nikita Koloff. Rick Rude, fresh off a count-out win over Dustin Rhodes and with Paul E. Dangerously suddenly in the picture, meets Rick Steiner. Paul Orndorff, red-hot after an upset of Steiner in Philadelphia and a classic with Tommy Rich in Richmond, gets the Junk Yard Dog. Brian Pillman and Jushin Liger run back their Philadelphia thriller."], ["p", "And whoever leaves Baltimore with the new belt won't have long to enjoy it. Ron Simmons is waiting. So is Koloff, who still wants Luger after Philadelphia. And somewhere in Memphis, a man in a robe is telling anyone who'll listen that the real world's championship never left his shoulder."], ["p", "The throne sits empty for five more days."]], "facts": [["Event", "The Great American Bash '91"], ["Date", "Sunday, July 14, 1991"], ["Venue", "Baltimore Arena, Baltimore, MD"], ["Match", "Steel cage, vacant WCW World Heavyweight Title"], ["In Luger's corner", "Harley Race"], ["Last time out", "Luger d. Koloff (7/5); Windham d. Ozz (7/6)"]]}, "wcw-observer-charleston-0712": {"p": "wcw", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-12", "region": "Atlanta Report", "kicker": "WCW · McAllister Fieldhouse, July 12", "title": "Charleston: Best Card, Smallest House", "dek": "The best-rated house show of the loop draws the smallest crowd since Flair left. Morton and Garvin miss the building, and Paul E. takes an interest in Larry Zbyszko.", "factTitle": "Match observations", "facts": [["Venue", "McAllister Fieldhouse"], ["City", "Charleston, SC"], ["Date", "July 12, 1991 (GAB tour, house show)"], ["Attendance", "3,200"], ["Average ticket", "$12.00"], ["Gate", "$38,400.00"], ["Merchandise", "$9,600.00 ($3.00 per fan)"], ["Card", "***"]], "body": [["p", "WCW drew 3,200 paying $38,400 to the McAllister Fieldhouse on Friday night, a little over half of a building that holds about 6,000. That's the smallest regular house show crowd and the lowest gate since Flair left, down 2,000 people and $24,000 from Columbia the night before. Merchandise was $9,600, about $3 a head, after Columbia did $10 a head. The best-rated house show of the loop drew the worst house, which tells you the TV isn't selling these shows yet. Two nights in the same state before the Bash didn't help either."], ["p", "The last house show before the Bash was rated ***, the best house show rating since Philadelphia and a quarter star up on Columbia. It was also the night two guys didn't make the building. Richard Morton and Jimmy Garvin both no-showed, so Jushin Liger got Terry Taylor instead of Morton, and Diamond Dallas Page filled Garvin's spot opposite Pillman and Rich. Nobody in the office is saying why. Two no-shows two nights before the biggest show of the summer is not the look WCW wants, and you can bet Jim Herd will ask about it."], ["p", "Sting beat Arn Anderson in the main when Arn passed out in the Scorpion Deathlock at 21:43 (***3/4). It's the first house show in a while where the main event was clearly the best thing on the card, and Arn was terrific at working the leg. Sting goes into Koloff on Sunday as strong as he has been all year."], ["p", "Rick Steiner beat the Great Muta at 15:27 (***3/4). It matched the main for match of the night. Steiner has had a strange tour, losing to Orndorff in Philly and then winning the main in Columbus, but tonight he looked like a man who belongs on top. The Rude match on Sunday needs this version of him."], ["p", "Brian Pillman and Tommy Rich beat Michael Hayes and DDP at 14:39 (***1/2), Pillman pinning Page with the flying cross body. With Garvin gone, Page worked as the third Freebird, which is exactly the role he plays in the Bash six-man, so the no-show did the six-man a favor."], ["p", "Ron Simmons beat Larry Zbyszko with the powerslam at 13:04 (***). The sim had Paul E. Dangerously interfere against Simmons, which nobody had planned. Paul E. now has interference logged in five matches across three shows: Eaton three times, Rude once and now Zbyszko. Zbyszko is a natural fit for whatever Paul E. is building, and he wrestles Arn on Sunday. Arn lost here, loses to Steiner in the TV tournament on WCW Pro, and Paul E. was already planning to pitch him the \"alone, you lose\" line. Paul E. getting both men would be a very strong opening roster for his group."], ["p", "Barry Windham pinned Mr. Hughes with a superplex at 14:45 (**1/2). Luger was at ringside with Harley Race. It was the clean win Windham needed after the Columbia DQ. This was Race's last house show at ringside as an active wrestler; he's manager-only from Sunday on."], ["p", "The rest: - Jushin Liger d. Terry Taylor, moonsault, 16:46, **1/2. A rematch of the Atlanta TV opener (***1/2), and it didn't come close. Taylor had no partner in the corner and no story to work with. - Bobby Eaton d. Robert Gibson, Alabama Jam, 13:04, *1/4. Paul E. interfered. That's the third logged Paul E. assist for Eaton on the tour. - Paul Orndorff d. Big Josh, piledriver, 8:06, **. Orndorff is unbeaten on the tour and on to JYD at the Bash. - Cactus Jack d. Black Bart, double-arm DDT, 8:30, *1/4. Cactus is still waiting for his WCW Pro storyline to air, starting Saturday morning. - Young Pistols d. Bill Irwin & Butch Reed, Smothers pinned Irwin after a dropkick, 12:19, 1/2*. Twelve minutes was too long for this."]]}, "wcw-diary-liger-0712": {"p": "wcw", "series": "diary", "by": "Jushin Liger", "date": "1991-07-12", "place": "Motel off Rivers Avenue, North Charleston", "kicker": "From the Road · Charleston, July 12", "title": "The Opponent Changes", "dek": "Jushin Liger found out at seven o'clock that he was wrestling Terry Taylor instead of Richard Morton.", "factTitle": "The Night", "facts": [["Show", "WCW house show, Charleston"], ["Match", "Jushin Liger d. Terry Taylor"], ["Finish", "Moonsault, 16:46"], ["Rating", "**1/2"]], "body": [["p", "At four o'clock I knew I was wrestling Richard Morton. At seven o'clock I knew I was wrestling Terry Taylor. Nobody told me what happened to Morton. In Japan, if a man misses the building, everybody knows by the next morning and the office decides what to do with him. Here they just change the sheet on the wall and keep going."], ["p", "I liked wrestling Taylor in Atlanta. He is a good technician and he works hard. But in Atlanta the TV cameras were there and the crowd was close to the ring. Tonight the building was hot and the people did not know him very well without his partner. I tried to give them reasons to cheer. The springboard plancha woke them up, and when I went up for the moonsault I could hear them stand. Sixteen minutes. I think it was too long for what we had. I will remember that."], ["p", "My mask was so wet by the end that I could not see well out of the left eye. South Carolina in July is like Osaka in August, but nobody gives you a cold towel at the curtain."], ["p", "In the back I watched Steiner and Muta. Mutoh-san and I came up in the same dojo, so I always watch him. He was very good tonight, and Steiner was very strong. That match and the Sting match were the best of the night. Arn Anderson worked on Sting's leg for twenty minutes like a carpenter. I want to learn how he does that without wasting a single movement."], ["p", "Sunday is Pillman again in Baltimore. He beat me in Philadelphia with the crucifix and I have not forgotten. He shook my hand on television, and I meant it. I will still try very hard to beat him."], ["p", "After Baltimore the schedule says Mexico, Acapulco on the 17th, then back to New Japan. My body is tired, but I am happy. Every night here I learn something about how Americans watch wrestling. Tonight I learned that if the opponent changes, the story has to change too."]]}, "wcw-sting-makes-arn-pass-out": {"p": "wcw", "kicker": "WCW Magazine · Road to the Bash · Charleston, July 12", "title": "Sting Makes the Enforcer Pass Out!", "dek": "Two nights before Baltimore, Sting locks Arn Anderson in the Scorpion, Windham gets his receipt from Mr. Hughes, and Paul E. is everywhere.", "by": "By the WCW Magazine staff", "date": "1991-07-12", "body": [["h", "Sting Makes The Enforcer Pass Out!"], ["p", "Two nights before he defends the United States Title against Nikita Koloff in Baltimore, Sting sent a message the whole Four Horsemen legacy will feel. For nearly twenty-two minutes Arn Anderson went after the champion's knee, his back and his patience, and for most of that time it looked like the Enforcer had a plan. Then Sting caught him, turned him over and locked in the Scorpion Deathlock. Arn wouldn't give up. He passed out instead, and the referee called it at 21:43."], ["p", "Sting stood in the middle of the ring with the belt over his shoulder and pointed toward Baltimore. Nikita, he's ready."], ["h", "Windham Gets His Receipt"], ["p", "One night after Mr. Hughes cost him in Columbia, Barry Windham got the big man alone. Harley Race barked from the floor and Lex Luger watched every move from ringside, but Windham wouldn't be stopped. He climbed to the top rope, brought all four hundred pounds of Hughes down with a superplex and covered him in the middle of the ring at 14:45. Then he looked straight at Luger. Neither man said a word. They don't need to. On Sunday they'll be locked inside a steel cage with the WCW World Title hanging above them."], ["h", "Steiner Stops The Muta"], ["p", "Rick Steiner and the Great Muta tore into each other for over fifteen minutes, with Steiner tossing the Japanese star across the ring and Muta answering with kicks and that terrifying mist. In the end the Dog-Faced Gremlin was too strong, pinning Muta at 15:27. That's a big win heading into Sunday, when Steiner faces Ravishing Rick Rude."], ["h", "Pillman Flies Again"], ["p", "Brian Pillman needed to bounce back after his loss to Bobby Eaton in Columbia, and he did. With Jimmy Garvin missing from the building, Diamond Dallas Page stepped in alongside Michael Hayes, and it was Page who paid for it. Pillman and Tommy Rich kept the pace high, and Flyin' Brian came off the top with a cross body to pin Page at 14:39."], ["h", "Paul E. Is Everywhere"], ["p", "Paul E. Dangerously had a busy night. First he made sure Bobby Eaton beat Robert Gibson, cracking Gibson with that portable phone before Eaton finished him with the Alabama Jam. Later he showed up during Ron Simmons vs. Larry Zbyszko and tried to tip that one too. It didn't work. Simmons shrugged it off and planted Zbyszko with the powerslam. Why does Paul E. care about Larry Zbyszko? Arn Anderson might want to know before Sunday."], ["h", "Around The Ring"], ["p", "Richard Morton was a no-show, so Jushin Liger faced Terry Taylor instead and stopped the York Foundation member with the moonsault in a 16:46 thriller. Mr. Wonderful Paul Orndorff dropped Big Josh with the piledriver. Cactus Jack went wild with Black Bart before finishing him with the double-arm DDT. And the Young Pistols opened the show with a win over Bill Irwin and Butch Reed when Tracy Smothers pinned Irwin after a dropkick."], ["h", "The Great American Bash: Sunday, July 14, Baltimore Arena"], ["p", "Steel Cage, for the vacant WCW World Title: Lex Luger vs. Barry Windham. U.S. Title: Sting vs. Nikita Koloff. Rick Rude vs. Rick Steiner. Brian Pillman vs. Jushin Liger. Paul Orndorff vs. Junk Yard Dog. Arn Anderson vs. Larry Zbyszko. Six-man: the Fabulous Freebirds and Diamond Dallas Page vs. the Young Pistols and Big Josh. And much more!"]], "factTitle": "Charleston Results", "facts": [["Main", "Sting d. Arn Anderson (Scorpion, 21:43)"], ["Co-main", "Windham d. Mr. Hughes (superplex)"], ["Also", "Steiner d. Muta; Pillman & Rich d. Hayes & DDP"], ["Next", "The Great American Bash, Sunday 7/14"]]}, "wcw-zenk-signs": {"p": "wcw", "news": 1, "by": "Newsletter staff", "date": "1991-07-11", "kicker": "WCW · Roster", "title": "The Z-Man Signs with WCW", "dek": "Tom Zenk is officially on the WCW roster as of July 11, and he'll be in Baltimore on Sunday.", "factTitle": "The Signing", "facts": [["Wrestler", "Tom Zenk, \"The Z-Man\""], ["Signed", "July 11, 1991"], ["Promotion", "WCW"], ["First appearance", "The Great American Bash, July 14"]], "body": [["p", "Tom Zenk has signed with World Championship Wrestling, effective July 11. The Z-Man had been advertised for the Great American Bash against Brian Pillman on the original card before he was under contract; that spot went to Jushin Liger for the Pillman rematch."], ["p", "Zenk will appear at the Great American Bash in Baltimore on Sunday. Paul E. Dangerously has told anyone who will listen that he has been on the phone with the Z-Man since the day he signed."]]}, "wcw-observer-pro-ep1": {"p": "wcw", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-13", "region": "Atlanta Report", "kicker": "WCW Pro · Episode 1, aired July 13", "title": "WCW Pro Ep. 1: The Tournament Starts, Sullivan Is Written Off", "dek": "Steiner and Orndorff advance, Paul E. promises Greenville, and Dustin Rhodes' sit-down is the best thing on the show.", "factTitle": "Match observations", "facts": [["Venue", "Leon County Civic Center"], ["City", "Tallahassee, FL"], ["Date", "Taped July 9; aired July 13, 1991"], ["Attendance", "5,200 (at the taping)"], ["Average ticket", "$12.00"], ["Gate", "$62,400.00 (all four episodes)"], ["Merchandise", "$7,800.00 ($1.50 per fan)"], ["Card", "**1/4"]], "body": [["p", "The first of four WCW Pro episodes from the Tallahassee taping aired Saturday morning and rated **1/4. It's a TV show with two squashes and a lot of talking, so the rating doesn't mean much on its own. The taping drew 5,200 at $12 for $62,400, plus $7,800 in merchandise at $1.50 a head, and that one crowd covers all four episodes. The point of the hour was to launch the TV Title tournament and push people toward Greenville and the Bash, and it did both."], ["p", "The tournament is eight men, single elimination, run over all four episodes. Two quarterfinals aired. Rick Steiner beat Arn Anderson in the main with the Steiner Bulldog at 12:26 for **1/2, and Paul Orndorff pinned Terry Taylor with the piledriver at 8:32 for *3/4. Both went the way you'd expect. Orndorff vs. Taylor was the disappointment. Orndorff has gone ****1/2 with Steiner in Philly and ****1/4 with Tommy Rich in Richmond, so *3/4 is a big drop, and Taylor was also flat with Liger in Charleston the night before this aired. The bracket is set up for Orndorff and Steiner to meet in the final, which would be their third match since Philly."], ["p", "Steiner and Arn was solid, though not great. Arn now has two straight losses (Sting in Charleston on Friday, this on TV Saturday) heading into his Bash match with Larry Zbyszko. Paul E. Dangerously, who interfered for Zbyszko in Charleston, has started telling Bischoff on TV that he \"makes investments.\" If Arn loses again Sunday, the pitch writes itself."], ["p", "The Killer Bees beat Dick Murdoch and Butch Reed at 7:52 (**1/2) when Blair cradled Murdoch. This is a WCW Pro-only feud that's supposed to run all four weeks and blow off with a no-DQ, no-masks match on 8/3. It's a nice idea for a B show. The Bees have been on the wrong end of the Bruise Brothers and the Freebirds on the house show loop, so they need this."], ["p", "The Paul E. promo was good. He took credit for Eaton and Rude and promised that Greenville tonight will show everyone \"what an investment looks like.\" That's an obvious tease for the Dustin Rhodes angle. Dustin is hurt, out until the fall, and the office is going to use the injury rather than lose him from TV entirely. His taped sit-down, wearing a neck brace, was the best thing on the show. He said he'll be in Greenville tonight and dared Paul E. to say it to his face, which tells you how tonight ends."], ["p", "The Dark Circle segment dealt with Kevin Sullivan's exit, which happened backstage in Columbus on Monday. Hughes and OMG came out, lit the candles, and nobody came. Hughes walked out, leaving OMG alone. It's a clean way to write Sullivan off TV without saying a word about why he left. Hughes has been working as Lex Luger's bodyguard all week anyway. The word is that Cactus Jack is being groomed to take over the group on the next three episodes."], ["p", "Windham squashed Dana McKinney with the superplex, and the Freebirds beat the Twilight Zone team, with Hayes pinning #2. Neither was rated."], ["p", "Next week's Pro, airing 7/20 after the Bash, has the other two quarterfinals: Zbyszko vs. Robert Gibson and Tommy Rich vs. Bobby Eaton with Paul E."]]}, "wcw-diary-steiner-0709": {"p": "wcw", "series": "diary", "by": "Rick Steiner", "date": "1991-07-09", "place": "Motel on Apalachee Parkway, Tallahassee", "kicker": "From the Road · Tallahassee taping, July 9", "title": "Long Day, Short Match, Bad Knee", "dek": "Rick Steiner beats Arn Anderson in the TV Title tournament, watches the Dark Circle fall apart, and calls his brother in Memphis.", "factTitle": "The Night", "facts": [["Show", "WCW Pro taping (Ep. 1 airs 7/13)"], ["Match", "Rick Steiner d. Arn Anderson"], ["Finish", "Steiner Bulldog, 12:26"], ["Rating", "**1/2"]], "body": [["p", "TV tapings are long days. We got to the building at two, and I didn't wrestle until after nine. They taped four shows' worth of stuff tonight, and the office kept moving guys around the board all afternoon. I watched about half of it from a folding chair by the curtain eating peanuts out of a bag."], ["p", "They put me in the main event of the first episode against Arn Anderson, in this TV Title tournament they're starting. I like working Arn. He doesn't waste anything. He went after my knee the whole match, just kicking it and wrenching it and talking to me the whole time. \"You want it, Rick? Come get it.\" By the end I couldn't feel my foot. But I caught him coming off the ropes and hit the Bulldog, and that was it. Twelve minutes. Arn shook my hand in the back and said, \"Good luck Sunday. You'll need it.\" He wasn't talking about the tournament."], ["p", "Sunday is Rude. Everybody says he's hurt guys on this tour, and that Paul E. guy has been following him around like a shadow. I saw Paul E. cut his promo with Bischoff tonight. He talks like a car salesman, but he's smart. Somebody's going to get hurt this week, and I don't want it to be me."], ["p", "I watched the Dark Circle thing from the back, too. Hughes and the One Man Gang came out, lit those candles, and just stood there. Sullivan never showed. Then Hughes walked off and left Gang out there by himself. Nobody in the locker room knows where Kevin went. Half the guys think he's in Memphis."], ["p", "Speaking of Memphis, I called Scott from the pay phone at the gas station across the street. He's doing good down there with the USWA. Says the crowds are loud and the money's short. Sounds about right. I told him about the tournament and he laughed and said, \"Win the belt, and then come get me.\""], ["p", "Orndorff won his match, too. If the bracket goes the way it looks, it's going to be me and him at the end. He beat me in Philly. I haven't forgotten that, and neither has he."], ["p", "Ice on the knee, two aspirin, and lights out. Columbia on Thursday."]]}, "wcw-steiner-draws-first-blood": {"p": "wcw", "kicker": "WCW Magazine · WCW Pro Report · Aired July 13", "title": "The Dog-Faced Gremlin Draws First Blood", "dek": "Steiner and Orndorff advance in the TV Title tournament, Paul E. issues a warning, and the Dark Circle is broken.", "by": "By the WCW Magazine staff", "date": "1991-07-13", "body": [["h", "The Dog-Faced Gremlin Draws First Blood"], ["p", "The WCW Television Championship is up for grabs, and Rick Steiner made sure everyone knows he wants it. In the main event of WCW Pro, Steiner went twelve rugged minutes with the Enforcer, Arn Anderson, in the first round of the TV Title tournament. Arn went after Steiner's knee from the opening bell and seemed to have him grounded, but Steiner kept getting up. When he finally caught Arn coming off the ropes, he hit the Steiner Bulldog and pinned him at 12:26."], ["p", "Steiner moves on to the semifinals. He has bigger business tomorrow night, though: Ravishing Rick Rude at the Great American Bash."], ["h", "Mr. Wonderful Rolls On"], ["p", "Paul Orndorff wasted no time in the other quarterfinal. Terry Taylor gave him a fight, but Orndorff dropped him with the piledriver at 8:32, and Mr. Wonderful strutted out of the ring like he already owns the belt. Next for Orndorff is the winner of Larry Zbyszko vs. Robert Gibson. Steiner waits for the winner of Tommy Rich vs. Bobby Eaton."], ["h", "Paul E. Has A Warning"], ["p", "Paul E. Dangerously told Eric Bischoff he doesn't manage wrestlers. He makes investments. He took credit for Bobby Eaton's summer and for Rick Rude's win over Dustin Rhodes in Richmond, and then he promised that Saturday night in Greenville the whole locker room will see \"what an investment looks like.\""], ["p", "Dustin Rhodes heard him. In a taped interview, wearing a neck brace, Dustin admitted he won't be cleared for Baltimore and won't say how long he'll be out. But he said he'll be in Greenville tonight to face the fans himself, and he told Paul E. to say it to his face."], ["h", "The Circle Is Broken"], ["p", "Kevin Sullivan has vanished. Mr. Hughes and the One Man Gang came to the ring in Tallahassee, lit the candles and waited for their leader. He never came. Then Mr. Hughes shook his head and walked out, leaving OMG alone in the middle of the candles. Has Hughes chosen Lex Luger? And who will lead what's left of the Dark Circle?"], ["h", "Around The Ring"], ["p", "The Killer Bees beat Dick Murdoch and Butch Reed when B. Brian Blair rolled up Murdoch with a bodyscissors cradle at 7:52. Murdoch insisted the man who pinned him wasn't the man who started the match, and he may have a point. Barry Windham tuned up for the cage with a superplex on Dana McKinney, and the Fabulous Freebirds took care of the Twilight Zone with Michael Hayes getting the pin."], ["h", "The Great American Bash: Sunday, July 14, Baltimore Arena"], ["p", "Steel Cage, for the vacant WCW World Title: Lex Luger vs. Barry Windham. U.S. Title: Sting vs. Nikita Koloff. Rick Rude vs. Rick Steiner. Brian Pillman vs. Jushin Liger. Paul Orndorff vs. Junk Yard Dog. Arn Anderson vs. Larry Zbyszko. Cactus Jack vs. Big Van Vader. And much more!"]], "factTitle": "WCW Pro Ep. 1", "facts": [["Main", "Steiner d. Arn Anderson (Steiner Bulldog)"], ["Also", "Orndorff d. Terry Taylor (piledriver)"], ["Pro-only", "Killer Bees d. Murdoch & Reed"], ["Next", "Saturday Night, Greenville; the Bash Sunday"]]}});

CONTRACTS.wcw = {"basis": "Monthly salary", "unit": "per month", "revenue": "July 5–12: $513,200 from seven dates (including the Tallahassee WCW Pro taping) plus $69,400 in merchandise. A full month of about 12 dates plus the Bash runs roughly $1M at the gate, plus TBS money.", "target": "Monthly payroll at about 40% of the gate. Turner TV money covers anything over.", "how": "Flat monthly salary, paid whether or not he works every date. Part-timers who also work Japan (Rude, Abdullah, Liger, Muta, Vader) are paid a reduced monthly figure. PPV main-event bonus: 5% of the PPV gate split by the main event. Managers and announcers are on the same scale.", "classes": [], "rows": [["A", "Lex Luger", 25000, "World Title, cage at the Bash"], ["A", "Sting", 25000, "U.S. Champion"], ["A", "Barry Windham", 16000, ""], ["A", "Rick Rude", 14000, "Part-time, also AJPW"], ["A", "Big Van Vader", 12000, "Part-time, also NJPW"], ["A", "Rick Steiner", 12000, ""], ["A", "Arn Anderson", 12000, ""], ["B", "Paul Orndorff", 10000, ""], ["B", "Nikita Koloff", 10000, "Leaves WCW in August"], ["B", "Brian Pillman", 8000, ""], ["B", "Larry Zbyszko", 8000, ""], ["B", "Ron Simmons", 8000, ""], ["B", "Cactus Jack", 8000, "Dark Circle leader"], ["B", "Jushin Liger", 7000, "Part-time, also NJPW"], ["B", "Great Muta", 7000, "Part-time"], ["B", "Bobby Eaton", 7000, ""], ["B", "Michael Hayes", 7000, ""], ["B", "El Gigante", 7000, ""], ["B", "Dustin Rhodes", 7000, "Injured, neck"], ["B", "Tom Zenk", 7000, "Signed 7/11/91. Debuts at the Bash"], ["B", "Abdullah The Butcher", 6000, "Part-time, also AJPW"], ["B", "Jimmy Garvin", 6000, ""], ["B", "One Man Gang", 6000, ""], ["C", "Junk Yard Dog", 5000, ""], ["C", "Dick Murdoch", 5000, ""], ["C", "Butch Reed", 5000, ""], ["C", "Richard Morton", 5000, ""], ["C", "Terry Taylor", 5000, ""], ["C", "B. Brian Blair", 4000, ""], ["C", "Jim Brunzell", 4000, ""], ["C", "Tommy Rich", 4000, ""], ["C", "Robert Gibson", 4000, ""], ["C", "Mr. Hughes", 4000, ""], ["C", "PN News", 4000, ""], ["C", "Don Harris", 4000, "Also TWA"], ["C", "Ron Harris", 4000, "Also TWA"], ["D", "Steve Armstrong", 3500, ""], ["D", "Tracy Smothers", 3500, ""], ["D", "Diamond Dallas Page", 3000, ""], ["D", "Big Josh", 3000, ""], ["D", "Black Bart", 3000, ""], ["D", "Bill Irwin", 3000, ""], ["D", "Ozz", 2500, ""], ["M", "Harley Race", 6000, "Manager to the 7/14 Bash"], ["M", "Paul E. Dangerously", 6000, ""], ["M", "Alexandra York", 3500, "Manager: York Foundation"], ["O", "Jim Ross", 8000, "Lead announcer"], ["O", "Tony Schiavone", 6000, "Announcer"], ["O", "Eric Bischoff", 4000, "Interviewer"], ["O", "Gary Michael Cappetta", 2500, "Ring announcer"]], "total": 349500, "check": "Salaries total $349,500 a month: about 35% of a $1M month."};

